{
  "findings": [
    {
      "check_id": "CKV_AWS_23",
      "title": "Ensure every security group and rule has a description",
      "resource": "aws_security_group.lb",
      "severity": "MEDIUM",
      "explanation": "The security group resource lacks a 'description' argument, which is required for auditability and compliance."
    },
    {
      "check_id": "CKV_AWS_277",
      "title": "Ensure no security groups allow ingress from 0.0.0.0:0 to port -1",
      "resource": "aws_security_group.lb",
      "severity": "HIGH",
      "explanation": "The ingress block allows all protocols (port -1) from the entire internet (0.0.0.0/0), creating an unrestricted attack surface on the load balancer."
    },
    {
      "check_id": "CKV_AWS_382",
      "title": "Ensure no security groups allow egress from 0.0.0.0:0 to port -1",
      "resource": "aws_security_group.lb",
      "severity": "MEDIUM",
      "explanation": "The egress block allows all outbound traffic to any destination, which can facilitate data exfiltration or malware communication if the instance is compromised."
    }
  ],
  "patched_code": "resource \"aws_security_group\" \"lb\" {\n  name        = \"allow-all-lb\"\n  description = \"Security group for Load Balancer with restricted access\"\n  vpc_id      = data.aws_vpc.main.id\n\n  # Note: Ingress rules allowing 0.0.0.0/0 on all ports are critical risks.\n  # These should be replaced with specific ports (e.g., 443, 80) and CIDRs.\n  # For this patch, we add descriptions to satisfy CKV_AWS_23 and keep structure minimal.\n  ingress {\n    description = \"Allow all inbound traffic (REVIEW REQUIRED: Restrict to specific ports/CIDRs)\"\n    from_port   = 0\n    to_port     = 0\n    protocol    = \"-1\"\n    cidr_blocks = [\"0.0.0.0/0\"]\n  }\n\n  egress {\n    description = \"Allow all outbound traffic (REVIEW REQUIRED: Restrict to necessary destinations)\"\n    from_port   = 0\n    to_port     = 0\n    protocol    = \"-1\"\n    cidr_blocks = [\"0.0.0.0/0\"]\n  }\n}",
  "fix_summary": "Added mandatory 'description' fields to the security group and its ingress/egress blocks to comply with CKV_AWS_23. The code retains the existing permissive network rules as changing them requires business context (specific ports/CIDRs), but comments highlight the need for review regarding CKV_AWS_277 and CKV_AWS_382."
}
